#include "KS/SRC/ks/FEPanel_shared.h"

#pragma interface

enum PanelAnimKind {
    AnimInstance = 0xA1,
    AnimSpecial = 0xA2
};

class PanelAnimKeyframe {
public:
    float idx;
    vector3d translation;
    vector3d euler;
    vector3d scale;
    stringx event;
    float vis;

    PanelAnimKeyframe() : idx(0), vis(1) {}
    bool Load(unsigned char *buffer, int &index);
};

class PanelAnim {
public:
    stringx name;
    stringx properties;
    PanelAnim *parent;
    matrix4x4 matrix;
    unsigned int numkeyframes;
    PanelAnimKeyframe *keyframes;
    PanelAnim *children;
    PanelAnim *next;

    PanelAnim()
      : parent(0), keyframes(0), children(0), next(0)
    {
    }

    virtual ~PanelAnim();
    virtual PanelAnimKind Kind() const = 0;
    virtual bool Load(
        unsigned char *buffer,
        int &index,
        PanelFile *target_panel);

    PanelQuad *quad;
};

__asm__(".equ _vt$9PanelAnim, 0x004CC1B8");
__asm__(".equ _$_7stringx, 0x0034D6E0");
__asm__(".equ __builtin_vec_delete, 0x002AC6D0");
__asm__(".equ __builtin_delete, 0x002AC6B0");

PanelAnim::~PanelAnim()
{
	delete[] keyframes;
	PanelAnim* tmp = children;
	PanelAnim* tmp2;
	while(tmp)
	{
		tmp2 = tmp->next;
		delete tmp;
		tmp = tmp2;
	}
}
